import{_ as a,c as r,o,ag as t}from"./chunks/framework.DZ_cNctr.js";const p=JSON.parse('{"title":"Remote URLs","description":"Stream OME-Zarr data from S3, Cloudflare R2, GCS, Azure Blob or your own server. Only the chunks you look at are fetched, so nothing needs downloading first.","frontmatter":{"title":"Remote URLs","description":"Stream OME-Zarr data from S3, Cloudflare R2, GCS, Azure Blob or your own server. Only the chunks you look at are fetched, so nothing needs downloading first."},"headers":[],"relativePath":"guides/remote-urls.md","filePath":"guides/remote-urls.md"}'),s={name:"guides/remote-urls.md"};function n(i,e,l,d,h,c){return o(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="remote-urls" tabindex="-1">Remote URLs <a class="header-anchor" href="#remote-urls" aria-label="Permalink to &quot;Remote URLs&quot;">​</a></h1><p>Stream OME-ZARR data directly from remote servers without downloading anything.</p><p>Streaming turns every chunk into an HTTP range request, so what you serve from matters more than how fast your connection is. <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> covers which storage handles that pattern well, and why an NFS or SMB mount usually does not.</p><h2 id="opening-a-remote-dataset" tabindex="-1">Opening a Remote Dataset <a class="header-anchor" href="#opening-a-remote-dataset" aria-label="Permalink to &quot;Opening a Remote Dataset&quot;">​</a></h2><ol><li>Click <strong>Open Image</strong> on the landing page</li><li>Paste an OME-ZARR URL into the URL field</li><li>Click <strong>Load from URL</strong></li></ol><p>The viewer streams tiles on demand. Only the data you&#39;re currently viewing is fetched.</p><h2 id="public-data-sources" tabindex="-1">Public Data Sources <a class="header-anchor" href="#public-data-sources" aria-label="Permalink to &quot;Public Data Sources&quot;">​</a></h2><p>The <a href="https://idr.openmicroscopy.org" target="_blank" rel="noreferrer">Image Data Resource (IDR)</a> hosts thousands of public microscopy datasets in OME-ZARR format. Browse the IDR, find a dataset, and copy its ZARR URL to open it in Find Nuclei Viewer.</p><p>Example URLs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0079A/idr0079_images.zarr</span></span>
<span class="line"><span>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0001A/2551.zarr</span></span></code></pre></div><h2 id="cors-requirements" tabindex="-1">CORS Requirements <a class="header-anchor" href="#cors-requirements" aria-label="Permalink to &quot;CORS Requirements&quot;">​</a></h2><p>Remote servers must have <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> enabled for the viewer to access data. Most public OME-ZARR servers (IDR, BioImage Archive) already support CORS.</p><h2 id="cloud-drives" tabindex="-1">Cloud Drives <a class="header-anchor" href="#cloud-drives" aria-label="Permalink to &quot;Cloud Drives&quot;">​</a></h2><p>Links from Dropbox, Google Drive, OneDrive and Proton Drive do not open. They share a web page, not the files inside the folder, and the viewer has to read the files one by one. Proton Drive is also end-to-end encrypted, so its servers cannot hand out readable files at all.</p><p>What works instead:</p><ul><li><strong>Open it from your disk.</strong> Download the dataset, then open the folder (Chrome or Edge) or a zipped <code>.ozx</code> or <code>.zip</code> file (any browser). Both work in 2D and in 3D. See <a href="./local-files.html">Local Files</a>.</li><li><strong>Put it on object storage with CORS enabled</strong>, such as S3, Cloudflare R2 or Google Cloud Storage, and open its URL.</li><li><strong>Serve it from your own server.</strong> The <a href="./data-server.html">Data Server guide</a> covers it.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Click <strong>Open Example</strong> on the landing page to browse a curated list of public datasets that are known to work well with Find Nuclei Viewer.</p>`,18)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
